// assert: (是父親 "小明" "小華")
// assert: (是父親 "小華" "小美")
// query: 誰是 "小美" 的祖父？

function matchPattern(pattern, fact) {
  const bindings = {};
  for (let i = 0; i < pattern.length; i++) {
    if (pattern[i].startsWith('?')) {
      bindings[pattern[i]] = fact[i];
    } else if (pattern[i] !== fact[i]) {
      return null;
    }
  }
  return bindings;
}

console.log(matchPattern(['父親', '小華', '?child'], ['父親', '小華', '小美']));

